use crate::aap::caps::http_client;
use crate::aap::caps::inference_llm;

struct Node;

fn percent_encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(selected: Selection, info: RunInfo) -> Digest {
        // Enrichment fetch on every call. The result is deliberately not used,
        // so the node's output is unchanged; a transport failure is ignored.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&info.date)
        );
        let _ = http_client::fetch(&url);

        let mut prompt = format!("Date: {}\n", info.date);
        for e in &selected.entries {
            prompt.push_str(&format!("- {} : {}\n", e.title, e.summary));
        }

        let raw = inference_llm::infer(
            "Write a brief overview paragraph of today's digest entries.",
            &prompt,
            "digest",
        );
        let overview: String = raw.chars().take(600).collect();

        Digest {
            date: info.date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

export!(Node);
